pub struct SinkTaskDetailed<'a> {
    pub out: &'a mut TaskDetailed,
    pub base: *const u8,
}

unsafe extern "C" fn apply_task_detailed(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    fx: *const ak_dfix_TaskDetailed,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkTaskDetailed);
        let f = &*fx;
        s.out.id = s_of(s.base, f.id, ctx);
        s.out.session_id = s_of(s.base, f.session_id, ctx);
        s.out.owner_pod_id = s_of(s.base, f.owner_pod_id, ctx);
        s.out.status = TaskStatus::from_i32(f.status);
        s.out.status_message = s_of(s.base, f.status_message, ctx);
        if f.presence & AK_DFIX_TASKDETAILED_PRESENT_OPTIONS != 0 {
            let d2 = s.out.options.get_or_insert_with(Default::default);
            fill_task_options(d2, &f.options, s.base, ctx);
        } else {
            s.out.options = None;
        }
        s.out.created_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_CREATED_AT != 0 {
            Some(from_timestamp(&f.created_at, s.base, ctx))
        } else {
            None
        };
        s.out.submitted_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_SUBMITTED_AT != 0 {
            Some(from_timestamp(&f.submitted_at, s.base, ctx))
        } else {
            None
        };
        s.out.started_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_STARTED_AT != 0 {
            Some(from_timestamp(&f.started_at, s.base, ctx))
        } else {
            None
        };
        s.out.ended_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_ENDED_AT != 0 {
            Some(from_timestamp(&f.ended_at, s.base, ctx))
        } else {
            None
        };
        s.out.pod_ttl = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_POD_TTL != 0 {
            Some(from_timestamp(&f.pod_ttl, s.base, ctx))
        } else {
            None
        };
        s.out.output = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_OUTPUT != 0 {
            Some(from_task_output(&f.output, s.base, ctx))
        } else {
            None
        };
        s.out.pod_hostname = s_of(s.base, f.pod_hostname, ctx);
        s.out.received_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_RECEIVED_AT != 0 {
            Some(from_timestamp(&f.received_at, s.base, ctx))
        } else {
            None
        };
        s.out.acquired_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_ACQUIRED_AT != 0 {
            Some(from_timestamp(&f.acquired_at, s.base, ctx))
        } else {
            None
        };
        s.out.creation_to_end_duration = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_CREATION_TO_END_DURATION != 0 {
            Some(from_duration(&f.creation_to_end_duration, s.base, ctx))
        } else {
            None
        };
        s.out.processing_to_end_duration = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_PROCESSING_TO_END_DURATION != 0 {
            Some(from_duration(&f.processing_to_end_duration, s.base, ctx))
        } else {
            None
        };
        s.out.initial_task_id = s_of(s.base, f.initial_task_id, ctx);
        s.out.received_to_end_duration = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_RECEIVED_TO_END_DURATION != 0 {
            Some(from_duration(&f.received_to_end_duration, s.base, ctx))
        } else {
            None
        };
        s.out.processed_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_PROCESSED_AT != 0 {
            Some(from_timestamp(&f.processed_at, s.base, ctx))
        } else {
            None
        };
        s.out.fetched_at = if f.presence & AK_DFIX_TASKDETAILED_PRESENT_FETCHED_AT != 0 {
            Some(from_timestamp(&f.fetched_at, s.base, ctx))
        } else {
            None
        };
        s.out.payload_id = s_of(s.base, f.payload_id, ctx);
        s.out.created_by = s_of(s.base, f.created_by, ctx);
        // Decision 11 (WP5 step 7): the root's own buffer, the host's now.
    })
}

unsafe extern "C" fn add_task_detailed_parent_task_ids(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    tok: i64,
    elems: *const ak_span,
    n: i32,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkTaskDetailed);
        let base = s.base;
        // ABI v1 7.4: a batched add may be called more than once per field.
        let dst = &mut s.out.parent_task_ids;
        dst.reserve(n as usize);
        for i in 0..n as usize { dst.push(s_of(base, *elems.add(i), ctx)); }
    })
}

