/// What the host hands the codec as `obj` on decode: the destination, plus
/// the base pointer the spans are offsets into (ABI v1 section 7.4).
pub struct SinkTaskSummary<'a> {
    pub out: &'a mut TaskSummary,
    pub base: *const u8,
}

unsafe extern "C" fn apply_task_summary(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    fx: *const ak_dfix_TaskSummary,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkTaskSummary);
        let f = &*fx;
        s.out.id = s_of(s.base, f.id, ctx);
        s.out.session_id = s_of(s.base, f.session_id, ctx);
        if f.presence & AK_DFIX_TASKSUMMARY_PRESENT_OPTIONS != 0 {
            let d2 = s.out.options.get_or_insert_with(Default::default);
            fill_task_options(d2, &f.options, s.base, ctx);
        } else {
            s.out.options = None;
        }
        s.out.status = TaskStatus::from_i32(f.status);
        s.out.created_at = if f.presence & AK_DFIX_TASKSUMMARY_PRESENT_CREATED_AT != 0 {
            Some(from_timestamp(&f.created_at, s.base, ctx))
        } else {
            None
        };
        s.out.error = s_of(s.base, f.error, ctx);
        s.out.status_message = s_of(s.base, f.status_message, ctx);
        s.out.count_data_dependencies = f.count_data_dependencies;
        // Decision 11 (WP5 step 7): the root's own buffer, the host's now.
    })
}

