/// What the host hands the codec as `obj` on decode: the destination, plus
/// the base pointer the spans are offsets into (ABI v1 section 7.4).
pub struct SinkSurrogate<'a> {
    pub out: &'a mut Surrogate,
    pub base: *const u8,
}

unsafe extern "C" fn apply_surrogate(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    fx: *const ak_dfix_Surrogate,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkSurrogate);
        let f = &*fx;
        s.out.text = s_of(s.base, f.text, ctx);
        s.out.nested = if f.presence & AK_DFIX_SURROGATE_PRESENT_NESTED != 0 {
            Some(from_surrogate_inner(&f.nested, s.base, ctx))
        } else {
            None
        };
        s.out.raw = b_of(s.base, f.raw);
        // Decision 11 (WP5 step 7): the root's own buffer, the host's now.
    })
}

unsafe extern "C" fn add_surrogate_attrs(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    tok: i64,
    elems: *const ak_dfix_SurrogateAttrsEntry,
    n: i32,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkSurrogate);
        let base = s.base;
        // ABI v1 7.4: a batched add may be called more than once per field.
        let dst = &mut s.out.attrs;
        for i in 0..n as usize {
            let e = &*elems.add(i);
            dst.insert(s_of(base, e.key, ctx), s_of(base, e.value, ctx));
            // Decision 11: the entry's own buffer; the facade map has no bag for
            // it (U-map-entry), so it is taken and dropped.
        }
    })
}

unsafe extern "C" fn add_surrogate_texts(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    tok: i64,
    elems: *const ak_span,
    n: i32,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkSurrogate);
        let base = s.base;
        // ABI v1 7.4: a batched add may be called more than once per field.
        let dst = &mut s.out.texts;
        dst.reserve(n as usize);
        for i in 0..n as usize { dst.push(s_of(base, *elems.add(i), ctx)); }
    })
}

pub fn decode_with_surrogate(ctxs: DecCtxs, b: &[u8]) -> Result<Surrogate, i32> {
    let ctx = ctxs.surrogate;
    let mut out = Surrogate::default();
    let rc = unsafe {
        let mut sink = SinkSurrogate { out: &mut out, base: b.as_ptr() };
        let vt = ak_dvt_Surrogate {
            apply: Some(apply_surrogate),
            add_attrs: Some(add_surrogate_attrs),
            add_texts: Some(add_surrogate_texts),
        };
        ak_decode_Surrogate(ctx, &mut sink as *mut _ as *mut c_void, b.as_ptr(), b.len(), &vt)
    };
    if rc < 0 { Err(rc) } else { Ok(out) }
}

/// Replay one chunk of records (ABI v1 section 7.1: "walk heap arrays").
///
/// `toks` maps the token the CODEC minted, which is an index over the whole
/// parse, to the one `new_*` returned, which is an index into one host vector.
/// They coincide when a root has a single non-leaf slot and would not if it
/// had two, so the map is kept rather than the coincidence relied on.
///
/// **`OPAQUE` is R5's second half, for this family.** A replay is HOST code
/// calling host code, so rustc may inline `apply_*` and `add_*` into it and
/// specialise them; a push callback is reached through a vtable from across
/// the shared-library boundary and can never be. Subtracting the two families
/// without saying so would charge an optimiser difference to the interface.
/// With `OPAQUE`, every call goes through a `black_box`ed function pointer --
/// no inlining, no devirtualisation, no constant propagation -- which is the
/// same device the `core-native-opaque` arm already uses for the same reason.
/// A const generic, so the branch folds away in both instantiations.
unsafe fn replay_surrogate_g<const OPAQUE: bool>(
    ctx: *mut ak_dec_ctx,
    sink: *mut c_void,
    recs: &[u64],
    toks: &mut Vec<i64>,
) {
    macro_rules! c {
        ($f:expr) => {
            if OPAQUE { ::core::hint::black_box($f) } else { $f }
        };
    }
    for (h, body) in ak_rt::bdr::RecIter::new(recs) {
        match (h.op, h.slot) {
            (AK_BDR_APPLY, 0) => c!(apply_surrogate)(ctx, sink, body as *const ak_dfix_Surrogate),
            (AK_BDR_ADD, 1) => c!(add_surrogate_attrs)(
                ctx,
                sink,
                h.token,
                body as *const ak_dfix_SurrogateAttrsEntry,
                h.n as i32,
            ),
            (AK_BDR_ADD, 2) => c!(add_surrogate_texts)(
                ctx,
                sink,
                h.token,
                body as *const ak_span,
                h.n as i32,
            ),
            // A record for a slot this host does not know is a generator
            // disagreement, not wire input, so it fails the operation rather
            // than being skipped the way an unknown TAG is.
            _ => ak_fail(ctx as *mut c_void, AK_ERR_ABI, ::core::ptr::null(), 0),
        }
    }
}

